// В реальном проекте объявление связывается с файлом add_amd64.s:
//
// package main
// func AsmAdd(x, y int64) int64
//
// Файл add_amd64.s:
// #include "textflag.h"
//
// // func AsmAdd(x, y int64) int64
// TEXT ·AsmAdd(SB), NOSPLIT, $0-24
//     MOVQ x+0(FP), AX    // Загрузка первого аргумента x в регистр AX
//     MOVQ y+8(FP), BX    // Загрузка второго аргумента y в регистр BX
//     ADDQ BX, AX         // AX = AX + BX
//     MOVQ AX, ret+16(FP) // Запись суммы в слот возвращаемого значения
//     RET                 // Возврат из функции

// EmulatedAsmAdd симулирует поведение ассемблерной инструкции Plan 9 ADDQ
func EmulatedAsmAdd(x, y int64) int64 {
	// В регистрах x86_64:
	// MOVQ x, AX
	// ADDQ y, AX
	// MOVQ AX, ret
	return x + y
}

func main() {
	fmt.Println("=== Plan 9 Go Assembly Primer ===")
	fmt.Println("Directives:")
	fmt.Println("  TEXT ·Func(SB): Global function symbol entry")
	fmt.Println("  NOSPLIT:        Do not emit stack allocation preamble")
	fmt.Println("  $FrameSize-ArgSize: $0-24 indicates 0 stack locals, 24 bytes args")
	fmt.Println("Pseudo-registers:")
	fmt.Println("  FP: Frame Pointer for function arguments (virtual)")
	fmt.Println("  SB: Static Base pointing to global symbols")
	fmt.Println("  SP: Stack Pointer pointing to local frame")

	a, b := int64(100), int64(250)
	result := EmulatedAsmAdd(a, b)
	fmt.Printf("\nOperation: %d + %d = %d\n", a, b, result)
}

package main

import (
	"fmt"
	"math/rand"
	"time"
)

// MaxBranching использует условный переход:
//
// CMPQ a, b
// JLE  ret_b
// MOVQ a, ret
// RET
//
//go:noinline
func MaxBranching(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

// MaxBranchless симулирует инструкцию CMOV (Conditional Move):
//
// MOVQ a+0(FP), AX
// MOVQ b+8(FP), BX
// CMPQ AX, BX
// CMOVQLE BX, AX  // Если AX <= BX, копируем BX в AX (без прыжков!)
// MOVQ AX, ret+16(FP)
// RET
//
//go:noinline
func MaxBranchless(a, b int64) int64 {
	diff := a - b
	// На 64-битных системах знаковый сдвиг копирует старший бит знака
	signMask := diff >> 63 // 0 если a >= b; -1 (все единицы) если a < b
	return a - (diff & signMask)
}

func main() {
	const n = 20000000
	dataA := make([]int64, n)
	dataB := make([]int64, n)

	// Заполняем абсолютно случайными числами для провокации Branch Misprediction
	r := rand.New(rand.NewSource(time.Now().UnixNano()))
	for i := 0; i < n; i++ {
		dataA[i] = r.Int63n(10000)
		dataB[i] = r.Int63n(10000)
	}

	// 1. Тест с ветвлением
	start1 := time.Now()
	var sum1 int64
	for i := 0; i < n; i++ {
		sum1 += MaxBranching(dataA[i], dataB[i])
	}
	dur1 := time.Since(start1)

	// 2. Тест без ветвления (Branchless)
	start2 := time.Now()
	var sum2 int64
	for i := 0; i < n; i++ {
		sum2 += MaxBranchless(dataA[i], dataB[i])
	}
	dur2 := time.Since(start2)

	fmt.Println("=== Branching vs Branchless (CMOV) Benchmark ===")
	fmt.Printf("Iterations: %d unpredictable comparisons\n", n)
	fmt.Printf("Branching Max:  %v (%.2f ns/op)\n", dur1, float64(dur1.Nanoseconds())/n)
	fmt.Printf("Branchless Max: %v (%.2f ns/op)\n", dur2, float64(dur2.Nanoseconds())/n)
	if dur1 > dur2 {
		fmt.Printf("Branchless Speedup: %.2fx faster due to zero branch mispredictions!\n", float64(dur1)/float64(dur2))
	}

	if sum1 != sum2 {
		panic("results mismatch")
	}
}

