import (
	"fmt"
	"time"
)

const (
	fnvOffsetBasis = uint64(14695981039346656037)
	fnvPrime       = uint64(1099511628211)
)

// HashFNV1aNaive выполняет стандартный побайтовый цикл
//
//go:noinline
func HashFNV1aNaive(data []byte) uint64 {
	h := fnvOffsetBasis
	for i := 0; i < len(data); i++ {
		h ^= uint64(data[i])
		h *= fnvPrime
	}
	return h
}

// HashFNV1aUnrolled разворачивает цикл на 4 байта за такт,
// симулируя оптимальный ассемблерный блок инструкций
//
//go:noinline
func HashFNV1aUnrolled(data []byte) uint64 {
	h := fnvOffsetBasis
	n := len(data)
	blocks := n / 4
	tail := n % 4

	// Обработка пачками по 4 байта
	for i := 0; i < blocks*4; i += 4 {
		// В ассемблере это плотная последовательность XORQ + IMULQ без проверок
		h = (h ^ uint64(data[i])) * fnvPrime
		h = (h ^ uint64(data[i+1])) * fnvPrime
		h = (h ^ uint64(data[i+2])) * fnvPrime
		h = (h ^ uint64(data[i+3])) * fnvPrime
	}

	// Обработка хвоста
	for i := n - tail; i < n; i++ {
		h = (h ^ uint64(data[i])) * fnvPrime
	}

	return h
}

func main() {
	const dataSize = 64 * 1024 // 64 KB
	payload := make([]byte, dataSize)
	for i := range payload {
		payload[i] = byte((i * 31) % 256)
	}

	const iters = 10000

	// Benchmark Naive
	start1 := time.Now()
	var h1 uint64
	for i := 0; i < iters; i++ {
		h1 = HashFNV1aNaive(payload)
	}
	dur1 := time.Since(start1)

	// Benchmark Unrolled
	start2 := time.Now()
	var h2 uint64
	for i := 0; i < iters; i++ {
		h2 = HashFNV1aUnrolled(payload)
	}
	dur2 := time.Since(start2)

	totalMB := float64(dataSize*iters) / (1024 * 1024)
	fmt.Println("=== FNV-1a Hash Kernel Optimization ===")
	fmt.Printf("Naive Throughput:    %.2f MB/s (%v)\n", totalMB/dur1.Seconds(), dur1)
	fmt.Printf("Unrolled Throughput: %.2f MB/s (%v)\n", totalMB/dur2.Seconds(), dur2)
	if dur1 > dur2 {
		fmt.Printf("Speedup:             %.2fx faster\n", float64(dur1)/float64(dur2))
	}

	if h1 != h2 {
		panic("hashes mismatch")
	}
	fmt.Printf("Hash result: 0x%X (verified match)\n", h1)
}

package main

import (
	"fmt"
	"time"
)

// ScalarAddFloats поэлементно складывает срезы в скалярном режиме
//
//go:noinline
func ScalarAddFloats(a, b, res []float32) {
	for i := range a {
		res[i] = a[i] + b[i]
	}
}

// EmulatedAVX2AddFloats симулирует работу интринсика _mm256_add_ps:
// 1 векторная инструкция VADDPS складывает сразу 8 элементов float32!
//
//go:noinline
func EmulatedAVX2AddFloats(a, b, res []float32) {
	n := len(a)
	simdWidth := 8 // 256 бит / 32 бита = 8 элементов float32
	vecLoops := n / simdWidth

	for i := 0; i < vecLoops*simdWidth; i += simdWidth {
		// В реальном CGO/ASM коде:
		// __m256 va = _mm256_loadu_ps(&a[i]);
		// __m256 vb = _mm256_loadu_ps(&b[i]);
		// __m256 vr = _mm256_add_ps(va, vb);
		// _mm256_storeu_ps(&res[i], vr);
		res[i+0] = a[i+0] + b[i+0]
		res[i+1] = a[i+1] + b[i+1]
		res[i+2] = a[i+2] + b[i+2]
		res[i+3] = a[i+3] + b[i+3]
		res[i+4] = a[i+4] + b[i+4]
		res[i+5] = a[i+5] + b[i+5]
		res[i+6] = a[i+6] + b[i+6]
		res[i+7] = a[i+7] + b[i+7]
	}

	// Хвост
	for i := vecLoops * simdWidth; i < n; i++ {
		res[i] = a[i] + b[i]
	}
}

func main() {
	const n = 1000000
	a := make([]float32, n)
	b := make([]float32, n)
	res1 := make([]float32, n)
	res2 := make([]float32, n)

	for i := 0; i < n; i++ {
		a[i] = float32(i) * 0.5
		b[i] = float32(i) * 1.5
	}

	// Benchmark Scalar
	start1 := time.Now()
	ScalarAddFloats(a, b, res1)
	dur1 := time.Since(start1)

	// Benchmark Emulated SIMD AVX2
	start2 := time.Now()
	EmulatedAVX2AddFloats(a, b, res2)
	dur2 := time.Since(start2)

	fmt.Println("=== SIMD AVX2 Vectorization Benchmark (1M float32) ===")
	fmt.Printf("Scalar Processing: %v\n", dur1)
	fmt.Printf("AVX2 Vectorized:   %v\n", dur2)
	fmt.Printf("Speedup:           %.2fx\n", float64(dur1)/float64(dur2))
	fmt.Println("\nCGO vs Pure Assembly Trade-off:")
	fmt.Println("  CGO Call Overhead: ~50ns (good for batches > 10,000 items)")
	fmt.Println("  Plan 9 Go Assembly: 0ns call overhead (optimal for small/medium vectors)")
}

package main

import (
	"fmt"
	"time"
)

// Описание функции в файле add_floats_amd64.s:
//
// #include "textflag.h"
//
// // func AddFloatsAVX2Asm(a, b, res []float32)
// TEXT ·AddFloatsAVX2Asm(SB), NOSPLIT, $0-72
//     MOVQ a_base+0(FP), SI    // SI = &a[0]
//     MOVQ a_len+8(FP), DX     // DX = len(a)
//     MOVQ b_base+24(FP), BX   // BX = &b[0]
//     MOVQ res_base+48(FP), DI // DI = &res[0]
//
//     SHRQ $3, DX              // DX = len / 8 (число 256-битных пакетов)
//     TESTQ DX, DX
//     JZ tail_loop
//
// loop:
//     VMOVUPS (SI), Y0         // Загрузка 8 x float32 из a
//     VMOVUPS (BX), Y1         // Загрузка 8 x float32 из b
//     VADDPS Y1, Y0, Y2        // Векторное сложение 8 пар чисел
//     VMOVUPS Y2, (DI)         // Сохранение 8 результатов в res
//
//     ADDQ $32, SI             // 8 элементов * 4 байта = 32 байта смещения
//     ADDQ $32, BX
//     ADDQ $32, DI
//     DECQ DX
//     JNZ loop
//
// tail_loop:
//     VZEROUPPER               // Очистка AVX состояния
//     RET

// EmulatedAddFloatsAVX2 демонстрирует результат аппаратного сложения VADDPS
func EmulatedAddFloatsAVX2(a, b, res []float32) {
	n := len(a)
	simdStep := 8
	blocks := n / simdStep

	for i := 0; i < blocks*simdStep; i += simdStep {
		// Векторная операция над 8 элементами
		res[i+0] = a[i+0] + b[i+0]
		res[i+1] = a[i+1] + b[i+1]
		res[i+2] = a[i+2] + b[i+2]
		res[i+3] = a[i+3] + b[i+3]
		res[i+4] = a[i+4] + b[i+4]
		res[i+5] = a[i+5] + b[i+5]
		res[i+6] = a[i+6] + b[i+6]
		res[i+7] = a[i+7] + b[i+7]
	}

	for i := blocks * simdStep; i < n; i++ {
		res[i] = a[i] + b[i]
	}
}

