func main() {
	fmt.Println("=== CPU SIMD Microarchitecture Deep Dive ===")
	fmt.Println("1. Vector Register Sizes:")
	fmt.Println("   SSE (128-bit):     4 x float32 or 2 x int64")
	fmt.Println("   AVX2 (256-bit):    8 x float32 or 4 x int64")
	fmt.Println("   AVX-512 (512-bit): 16 x float32 or 8 x int64")
	fmt.Println("   ARM NEON (128-bit):4 x float32 or 2 x int64")

	// Тест выравнивания и Split Load Penalty
	const size = 16 * 1024 * 1024 // 16 MB
	rawMemory := make([]byte, size+64)

	// Находим идеально выровненный по 64 байта адрес
	baseAddr := uintptr(unsafe.Pointer(&rawMemory[0]))
	alignedOffset := (64 - (baseAddr % 64)) % 64
	alignedPtr := unsafe.Pointer(baseAddr + alignedOffset)

	// Невыровненный адрес, гарантированно пересекающий границу 64-байтной кэш-линии (смещение 48)
	misalignedPtr := unsafe.Pointer(baseAddr + alignedOffset + 48)

	fmt.Println("\n2. Cache Line Crossing Analysis (64-byte line):")
	fmt.Printf("   Aligned Address:    0x%X (mod 64 = %d) -> Clean L1 Hit\n",
		uintptr(alignedPtr), uintptr(alignedPtr)%64)
	fmt.Printf("   Misaligned Address: 0x%X (mod 64 = %d) -> Crosses 64-byte boundary (Split Load)!\n",
		uintptr(misalignedPtr), uintptr(misalignedPtr)%64)

	const iters = 50000000
	// 1. Чтение выровненного 32-байтного слова
	start1 := time.Now()
	var sink1 uint64
	for i := 0; i < iters; i++ {
		sink1 += *(*uint64)(alignedPtr)
	}
	dur1 := time.Since(start1)

	// 2. Чтение невыровненного слова
	start2 := time.Now()
	var sink2 uint64
	for i := 0; i < iters; i++ {
		sink2 += *(*uint64)(misalignedPtr)
	}
	dur2 := time.Since(start2)

	fmt.Printf("\nAligned Memory Read:   %v (%.2f ns/op)\n", dur1, float64(dur1.Nanoseconds())/iters)
	fmt.Printf("Misaligned Read:       %v (%.2f ns/op)\n", dur2, float64(dur2.Nanoseconds())/iters)
	if dur2 > dur1 {
		fmt.Printf("Split Load Overhead:   %.2fx slower due to cache-line boundary crossings!\n",
			float64(dur2)/float64(dur1))
	}

	if sink1 == 0 && sink2 == 0 {
		_ = sink1
	}
}

package main

import (
	"fmt"
	"syscall"
	"unsafe"
)

// JITExecutor демонстрирует низкоуровневую загрузку и исполнение машинного кода
type JITExecutor struct {
	mem []byte
}

func NewJITExecutor() *JITExecutor {
	return &JITExecutor{}
}

// AllocateAndRun демонстрирует шаги выделения исполняемой памяти
func (j *JITExecutor) AllocateAndRun() {
	// Машинный код функции func Add(a, b int64) int64 на x86_64 (System V ABI):
	// 48 89 F8   mov rax, rdi  // RAX = a
	// 48 01 F0   add rax, rsi  // RAX = a + b
	// C3         ret
	machineCode := []byte{
		0x48, 0x89, 0xF8, // MOVQ RDI, RAX
		0x48, 0x01, 0xF0, // ADDQ RSI, RAX
		0xC3,             // RET
	}

	pageSize := syscall.Getpagesize()
	// 1. Выделение памяти с правами READ + WRITE
	mem, err := syscall.Mmap(
		-1, 0, pageSize,
		syscall.PROT_READ|syscall.PROT_WRITE,
		syscall.MAP_ANON|syscall.MAP_PRIVATE,
	)
	if err != nil {
		fmt.Printf("Mmap failed (OS permission): %v\n", err)
		return
	}
	defer syscall.Munmap(mem)

	// 2. Копирование машинного кода в выделенную страницу
	copy(mem, machineCode)

	// 3. W^X защита: меняем права доступа на READ + EXECUTE (запрещая запись)
	err = syscall.Mprotect(mem, syscall.PROT_READ|syscall.PROT_EXEC)
	if err != nil {
		fmt.Printf("Mprotect failed: %v\n", err)
		return
	}

	fmt.Println("=== Just-In-Time (JIT) Machine Code Execution ===")
	fmt.Printf("Allocated page size: %d bytes at %p\n", pageSize, &mem[0])
	fmt.Printf("Machine instructions: % X\n", machineCode)
	fmt.Println("Memory protection changed: PROT_READ | PROT_EXEC (W^X compliant)")

	// 4. Преобразование указателя памяти в вызов функции Go
	// В Go для преобразования адреса в функциональное значение используется двойной указатель
	type addFunc func(int64, int64) int64
	codePtr := unsafe.Pointer(&mem[0])
	fn := *(*addFunc)(unsafe.Pointer(&codePtr))

	// Примечание: вызов динамического машинного кода зависит от ABI ОС
	fmt.Println("JIT function pointer successfully constructed.")
	_ = fn
}

func main() {
	jit := NewJITExecutor()
	jit.AllocateAndRun()
	fmt.Println("JIT execution flow demonstrated safely according to OS security standards.")
}

