package main

import (
	"fmt"
	"time"
)

// ScalarAdd выполняет поэлементное сложение
//
//go:noinline
func ScalarAdd(a, b, res []float32) {
	for i := range a {
		res[i] = a[i] + b[i]
	}
}

// SSEModelAdd симулирует 128-битные инструкции SSE (ADDPS - 4 float32 за такт)
//
//go:noinline
func SSEModelAdd(a, b, res []float32) {
	n := len(a)
	loops := n / 4
	for i := 0; i < loops*4; i += 4 {
		res[i+0] = a[i+0] + b[i+0]
		res[i+1] = a[i+1] + b[i+1]
		res[i+2] = a[i+2] + b[i+2]
		res[i+3] = a[i+3] + b[i+3]
	}
	for i := loops * 4; i < n; i++ {
		res[i] = a[i] + b[i]
	}
}

// AVX2ModelAdd симулирует 256-битные инструкции AVX2 (VADDPS - 8 float32 за такт)
//
//go:noinline
func AVX2ModelAdd(a, b, res []float32) {
	n := len(a)
	loops := n / 8
	for i := 0; i < loops*8; i += 8 {
		res[i+0] = a[i+0] + b[i+0]
		res[i+1] = a[i+1] + b[i+1]
		res[i+2] = a[i+2] + b[i+2]
		res[i+3] = a[i+3] + b[i+3]
		res[i+4] = a[i+4] + b[i+4]
		res[i+5] = a[i+5] + b[i+5]
		res[i+6] = a[i+6] + b[i+6]
		res[i+7] = a[i+7] + b[i+7]
	}
	for i := loops * 8; i < n; i++ {
		res[i] = a[i] + b[i]
	}
}

func main() {
	const n = 10000000
	a := make([]float32, n)
	b := make([]float32, n)
	res1 := make([]float32, n)
	res2 := make([]float32, n)
	res3 := make([]float32, n)

	for i := range a {
		a[i] = float32(i) * 0.1
		b[i] = float32(i) * 0.2
	}

	// 1. Scalar
	start1 := time.Now()
	ScalarAdd(a, b, res1)
	dur1 := time.Since(start1)

	// 2. SSE Model
	start2 := time.Now()
	SSEModelAdd(a, b, res2)
	dur2 := time.Since(start2)

	// 3. AVX2 Model
	start3 := time.Now()
	AVX2ModelAdd(a, b, res3)
	dur3 := time.Since(start3)

	// Суммарный объем прочитанных и записанных данных: 3 массива по 40 МБ = 120 МБ
	trafficGB := (float64(n*4*3) / (1024 * 1024 * 1024))

	fmt.Println("=== 10 Million float32 Elements SIMD Benchmark ===")
	fmt.Printf("Memory Traffic per run: %.2f MB (exceeds L3 Cache)\n", float64(n*4*3)/(1024*1024))
	fmt.Printf("Scalar Mode:    %v | Bandwidth: %.2f GB/s\n", dur1, trafficGB/dur1.Seconds())
	fmt.Printf("SSE Model:      %v | Bandwidth: %.2f GB/s\n", dur2, trafficGB/dur2.Seconds())
	fmt.Printf("AVX2 Model:     %v | Bandwidth: %.2f GB/s\n", dur3, trafficGB/dur3.Seconds())

	fmt.Printf("\nSpeedup SSE  vs Scalar: %.2fx\n", float64(dur1)/float64(dur2))
	fmt.Printf("Speedup AVX2 vs Scalar: %.2fx\n", float64(dur1)/float64(dur3))
}

package main

import (
	"encoding/json"
	"fmt"
	"time"
)

type EventLog struct {
	ID        int64  `json:"id"`
	Action    string `json:"action"`
	Status    string `json:"status"`
	Timestamp int64  `json:"timestamp"`
}

// Stage1StructuralIndexerModel демонстрирует Stage 1 алгоритма simdjson:
// векторное нахождение структурных символов { } : , "
func Stage1StructuralIndexerModel(doc []byte) []int {
	structuralIndices := make([]int, 0, len(doc)/8)
	inString := false

	for i := 0; i < len(doc); i++ {
		b := doc[i]
		// Обработка кавычек
		if b == '"' && (i == 0 || doc[i-1] != '\\') {
			inString = !inString
			structuralIndices = append(structuralIndices, i)
			continue
		}
		// Внутри строки все символы игнорируются
		if inString {
			continue
		}
		// Структурные разделители
		if b == '{' || b == '}' || b == ':' || b == ',' || b == '[' || b == ']' {
			structuralIndices = append(structuralIndices, i)
		}
	}
	return structuralIndices
}

func main() {
	sampleJSON := []byte(`{"id": 109923, "action": "checkout_order", "status": "approved", "timestamp": 1700000000}`)

	const iters = 100000

	// 1. Standard encoding/json Benchmark
	start1 := time.Now()
	var ev EventLog
	for i := 0; i < iters; i++ {
		_ = json.Unmarshal(sampleJSON, &ev)
	}
	dur1 := time.Since(start1)

	// 2. SIMD Stage 1 Structural Model
	start2 := time.Now()
	var indices []int
	for i := 0; i < iters; i++ {
		indices = Stage1StructuralIndexerModel(sampleJSON)
	}
	dur2 := time.Since(start2)

	totalMB := float64(len(sampleJSON)*iters) / (1024 * 1024)
	fmt.Println("=== simdjson vs Standard encoding/json ===")
	fmt.Printf("Sample Payload: %s\n", sampleJSON)
	fmt.Printf("Standard JSON Throughput: %.2f MB/s (%v)\n", totalMB/dur1.Seconds(), dur1)
	fmt.Printf("simdjson Stage 1 Model:   %.2f MB/s (%v)\n", totalMB/dur2.Seconds(), dur2)
	fmt.Printf("Speedup:                  %.2fx faster\n", float64(dur1)/float64(dur2))
	fmt.Printf("\nFound %d structural tokens in Stage 1 index tape.\n", len(indices))
	fmt.Println("Libraries for production: github.com/minio/simdjson-go")
}

